pattern = [[7,9,7],[2,7,2],[1,1,7]]

def generate_output(merge_rule='first'):
    """
    merge_rule: 'first' = first pattern wins, 'last' = last pattern wins, 
                'max' = max value wins, 'min' = min value wins, 
                'fill' = fill overlapping area with pattern (no skipping)
    """
    output = [[6]*cols for _ in range(rows)]

    zeros = [(12,6),(13,5),(13,7)]

    if merge_rule == 'first':
        for r0, c0 in zeros:
            for pr in range(3):
                for pc in range(3):
                    nr, nc = r0 + pr - 1, c0 + pc - 1
                    if 0 <= nr < rows and 0 <= nc < cols and output[nr][nc] == 6:
                        output[nr][nc] = pattern[pr][pc]

    elif merge_rule == 'last':
        for r0, c0 in zeros:
            for pr in range(3):
                for pc in range(3):
                    nr, nc = r0 + pr - 1, c0 + pc - 1
                    if 0 <= nr < rows and 0 <= nc < cols:
                        output[nr][nc] = pattern[pr][pc]

    elif merge_rule == 'max':
        for r0, c0 in zeros:
            for pr in range(3):
                for pc in range(3):
                    nr, nc = r0 + pr - 1, c0 + pc - 1
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if output[nr][nc] == 6 or output[nr][nc] < pattern[pr][pc]:
                            output[nr][nc] = pattern[pr][pc]

    elif merge_rule == 'min':
        for r0, c0 in zeros:
            for pr in range(3):
                for pc in range(3):
                    nr, nc = r0 + pr - 1, c0 + pc - 1
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if output[nr][nc] == 6 or output[nr][nc] > pattern[pr][pc]:
                            output[nr][nc] = pattern[pr][pc]

    elif merge_rule == 'opposite':
        # Maybe overlapping patterns should be REPLACED by background?
        for r0, c0 in zeros:
            for pr in range(3):
                for pc in range(3):
                    nr, nc = r0 + pr - 1, c0 + pc - 1
                    if 0 <= nr < rows and 0 <= nc < cols and output[nr][nc] == 6:
                        output[nr][nc] = pattern[pr][pc]

        # Clear overlapping areas (where multiple patterns would hit)
        overlap_r = range(12, 15)
        overlap_c = range(5, 9)
        for r in overlap_r:
            for c in overlap_c:
                for r0, c0 in zeros:
                    if (r0-1 <= r <= r0+1) and (c0-1 <= c <= c0+1):
                        # This cell is in multiple patterns, reset to 6
                        output[r][c] = 6

    return output

# Test each merge rule
